from __future__ import annotations

def remove_spaces(equation):
    return equation.replace(' ', '')

def validate_equation(equation):
    equation = remove_spaces(equation)
    if equation == '':
        return None
    if '0/' in equation or '0%' in equation:
        return None
    return equation

def calculate_expression(equation):
    if not equation:
        return None
    equation = equation.replace(' ', '')
    if not validate_equation(equation):
        return None
    stack = []
    operators = set('+-*/^%')
    i = 0
    while i < len(equation):
        if equation[i] in operators:
            stack.append(equation[i])
            i += 1
        else:
            num = 0
            while i < len(equation) and equation[i] not in operators:
                num = num * 10 + int(equation[i])
                i += 1
            stack.append(num)
    while len(stack) > 1:
        b = stack.pop()
        a = stack.pop()
        operator = stack.pop()
        if operator == '+':
            stack.append(a + b)
        elif operator == '-':
            stack.append(a - b)
        elif operator == '*':
            stack.append(a * b)
        elif operator == '/':
            stack.append(a // b)
        elif operator == '^':
            stack.append(a ** b)
        elif operator == '%':
            stack.append(a % b)
    return stack[0]

def no_order(equation):
    if not equation:
        return None
    equation = equation.replace(' ', '')
    if '/0' in equation or '%0' in equation:
        return None
    return calculate_expression(equation)

