from __future__ import annotations

def remove_spaces(equation):
    return equation.replace(' ', '')

def validate_equation(equation):
    equation = remove_spaces(equation)
    if equation == '':
        return None
    if '0/' in equation or '0%' in equation:
        return None
    return equation

def calculate_expression(equation):
    if not equation.strip():
        return None
    equation = equation.replace(' ', '')
    if not validate_equation(equation):
        return None
    tokens = []
    current_number = ''
    for char in equation:
        if char.isdigit() or char == '.':
            current_number += char
        else:
            if current_number:
                tokens.append(float(current_number))
                current_number = ''
            tokens.append(char)
    if current_number:
        tokens.append(float(current_number))
    result = tokens[0]
    for i in range(1, len(tokens), 2):
        operator = tokens[i]
        next_number = tokens[i + 1]
        if operator == '+':
            result += next_number
        elif operator == '-':
            result -= next_number
        elif operator == '*':
            result *= next_number
        elif operator == '/':
            result = result // next_number
        elif operator == '^':
            result **= next_number
        elif operator == '%':
            result %= next_number
    return result

def no_order(equation):
    if not equation:
        return None
    equation = equation.replace(' ', '')
    if '/0' in equation or '%0' in equation:
        return None
    return calculate_expression(equation)

