    if v1 >= v2:
        return -1.0
    time_diff = g / (v2 - v1)
    return time_diff

def convert_to_hms(seconds: float) -> list:
    hours = int(seconds // 3600)
    minutes = int(seconds % 3600 // 60)
    sec = int(seconds % 60)
    return [hours, minutes, sec]

def race(v1: int, v2: int, g: int) -> list:
    if v1 >= v2:
        return [-1, -1, -1]
    time_diff = time_difference(v1, v2, g)
    return convert_to_hms(time_diff * 3600)

