from __future__ import annotations

def remove_duplicate_letters(keyword):
    return ''.join(sorted(set(keyword), key=keyword.index))

def generate_encryption_key(keyword):
    """
    Generate the encryption key by removing duplicate letters from the keyword
    and appending the remaining letters of the alphabet.
    """
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    keyword = keyword.lower()
    unique_keyword = remove_duplicate_letters(keyword)
    remaining_letters = ''.join([letter for letter in alphabet if letter not in unique_keyword])
    encryption_key = unique_keyword + remaining_letters
    return encryption_key

def encrypt_message(msg, encryption_key):
    encrypted_msg = []
    for char in msg:
        if char in encryption_key:
            encrypted_msg.append(encryption_key.index(char))
    return ''.join(map(str, encrypted_msg))

def keyword_cipher(msg, keyword):
    keyword = ''.join(sorted(set(keyword.lower()), key=keyword.lower().index))
    encryption_key = keyword + ''.join([chr(i) for i in range(97, 123) if chr(i) not in keyword])
    return encrypt_message(msg, encryption_key)

