def remove_duplicate_letters(keyword: str) -> str:
    return ''.join(sorted(set(keyword), key=keyword.index))

def generate_encryption_key(keyword: str) -> str:
    return remove_duplicate_letters(keyword) + ''.join(sorted(set('abcdefghijklmnopqrstuvwxyz') - set(remove_duplicate_letters(keyword))))

def encrypt_message(msg: str, encryption_key: str) -> str:
    encrypted_msg = ''
    for char in msg:
        if char in encryption_key:
            encrypted_msg += encryption_key[encryption_key.index(char)]
    return encrypted_msg

def keyword_cipher(msg: str, keyword: str) -> str:
    keyword = ''.join(sorted(set(keyword.lower()), key=keyword.lower().index))
    encryption_key = keyword + ''.join((c for c in 'abcdefghijklmnopqrstuvwxyz' if c not in keyword))
    return encrypt_message(msg.lower(), encryption_key)

