def is_within_parentheses(s, index):
    balance = 0
    for i in range(index):
        if s[i] == '(':
            balance += 1
        elif s[i] == ')':
            balance -= 1
        if balance == 0:
            return True
    return False

def find_next_parenthesis(s, start_index):
    depth = 0
    for i in range(start_index, len(s)):
        if s[i] == '(':
            depth += 1
        elif s[i] == ')':
            depth -= 1
            if depth == 0:
                return i
    return -1

def remove_parentheses(s):
    result = []
    i = 0
    while i < len(s):
        if s[i] == '(':
            i = find_next_parenthesis(s, i) + 1
        else:
            result.append(s[i])
            i += 1
    return ''.join(result)

