def bubble(l):
    snapshots = []
    n = len(l)
    for i in range(n):
        for j in range(0, n - i - 1):
            if l[j] > l[j + 1]:
                swap_elements(l, j, j + 1)
                snapshots.append(l[:])
    return snapshots

