def is_uppercase(char: str) -> bool:
    return char.isupper()

def insert_space(text: str, index: int) -> str:
    return text[:index] + ' ' + text[index:]

def solution(s: str) -> str:
    result = []
    for i, char in enumerate(s):
        if char.isupper():
            result.append(insert_space(s, i))
        else:
            result.append(char)
    return ''.join(result)

